/* @lc app=leetcode id=2385 lang=kotlin */ class Solution { fun amountOfTime(root: TreeNode?, start: Int): Int = HashMap<Int, MutableList<Int>>().let { adj -> generateSequence(listOf(root!!)) { f -> f.flatMap { listOfNotNull(it.left, it.right) }.takeIf { it.isNotEmpty() } }.flatten().forEach { n -> listOfNotNull(n.left, n.right).forEach { c -> adj.getOrPut(n.`val`) { mutableListOf() }.add(c.`val`).also { adj.getOrPut(c.`val`) { mutableListOf() }.add(n.`val`) } } }.let { HashSet<Int>().also { it.add(start) }.let { seen -> generateSequence(listOf(start)) { f -> f.flatMap { adj[it].orEmpty() }.filter { seen.add(it) }.takeIf { it.isNotEmpty() } }.count() - 1 } } } }